#!/usr/bin/env python3
import parse_gau as pars
import os
import numpy as np

def calc(comname, writexyz, N, n, q, fchk, get, aulen):
    with open(writexyz, 'w') as f:
        for i in range(N):
            f.write('{0:<2s} {1[0]:>20.16f} {1[1]:>20.16f} {1[2]:>20.16f} \n'.format(n[i], np.multiply(q[3*i:3*i+3], aulen)))
    os.system('g16 {0}.com {0}.log'.format(comname))
    os.system('formchk {0}.chk {0}.fchk'.format(fchk))
    return pars.translate_gaussian('{}.fchk'.format(fchk), get)

def initcalc(comname, writexyz, N, n, q, fchk, get, aulen, init):
    return calc(comname, writexyz, N, n, q, fchk, get, aulen)

